/** Build a browser mesh from the GLB generated by export_cad.py; keep every instance addressable. */
import fs from 'node:fs';
import {MeshoptSimplifier, MeshoptEncoder} from 'meshoptimizer';

await Promise.all([MeshoptEncoder.ready, MeshoptSimplifier.ready]);
const input = process.argv[2] || 'public/assets/bpx.glb';
const output = process.argv[3] || 'public/assets/bpx-runtime.glb';
if (input === output) throw Error('Choose a separate output path for the browser mesh.');
const raw = fs.readFileSync(input);
const jsonLength = raw.readUInt32LE(12);
const doc = JSON.parse(raw.subarray(20,20+jsonLength));
const src = raw.subarray(28+jsonLength);
const types = {5123:Uint16Array,5125:Uint32Array,5126:Float32Array};
function read(index) {
  const a = doc.accessors[index], b = doc.bufferViews[a.bufferView], T = types[a.componentType];
  if (!T || b.byteStride) throw Error('Expected packed CAD accessors.');
  return new T(src.buffer,src.byteOffset+(b.byteOffset || 0)+(a.byteOffset || 0),a.count*(a.type === 'VEC3' ? 3 : 1));
}
const views = [], accessors = [], chunks = [];
let length = 0, virtualLength = 0;
function append(view, mode, size, count, accessor) {
  const bytes = new Uint8Array(view.buffer,view.byteOffset,view.byteLength);
  const packed = MeshoptEncoder.encodeGltfBuffer(bytes,count,size,mode);
  const pad = (4-length%4)%4;
  chunks.push(Buffer.alloc(pad),packed);
  length += pad;
  virtualLength += (4-virtualLength%4)%4;
  const bufferView = views.length;
  const normalView = {buffer:1,byteOffset:virtualLength,byteLength:bytes.length,target:mode==='TRIANGLES'?34963:34962};
  normalView.extensions = {EXT_meshopt_compression:{buffer:0,byteOffset:length,byteLength:packed.byteLength,
    byteStride:size,count,mode,filter:'NONE'}};
  views.push(normalView);
  length += packed.byteLength;
  virtualLength += bytes.length;
  accessors.push({bufferView,count,...accessor});
  return accessors.length-1;
}

const uses = new Map();
for (const n of doc.nodes) if(n.mesh !== undefined) uses.set(n.mesh,1+(uses.get(n.mesh)||0));
let before = 0, after = 0, maxError = 0;
for (let i=0; i<doc.meshes.length; ++i) {
  const mesh = doc.meshes[i];
  for (const primitive of mesh.primitives) {
    const pos = read(primitive.attributes.POSITION), norm = read(primitive.attributes.NORMAL);
    const ii = Uint32Array.from(read(primitive.indices));
    const target = Math.min(ii.length,3*Math.max(24,Math.floor(ii.length/3*0.20)));
    // Preserve normal discontinuities and every original boundary. Trimming a bore
    // shut or welding a thin shell together would break disassembly closeups.
    const errorBudget = /齿圈/.test(mesh.name) ? .13 : .19;
    const [out,error] = MeshoptSimplifier.simplifyWithAttributes(ii,pos,3,norm,3,
      [.12,.12,.12],null,target,errorBudget,['ErrorAbsolute','LockBorder','PreserveFolds']);
    maxError = Math.max(maxError,error);
    before += ii.length*uses.get(i)/3;
    after += out.length*uses.get(i)/3;
    const [remap,count] = MeshoptEncoder.reorderMesh(out,true,true);
    const newPos = new Float32Array(3*count), newNorm = new Float32Array(3*count);
    const min = [Infinity,Infinity,Infinity], max = [-Infinity,-Infinity,-Infinity];
    for(let j=0;j<pos.length/3;j++) {
      const dest = remap[j];
      if (dest===undefined || dest>=count) continue;
      for(let k=0;k<3;k++) {
        const val=pos[3*j+k];
        newPos[3*dest+k] = val;
        newNorm[3*dest+k] = norm[3*j+k];
        min[k]=Math.min(min[k],val);
        max[k]=Math.max(max[k],val);
      }
    }
    primitive.attributes.POSITION = append(newPos,'ATTRIBUTES',12,count,{componentType:5126,type:'VEC3',min,max});
    primitive.attributes.NORMAL = append(newNorm,'ATTRIBUTES',12,count,{componentType:5126,type:'VEC3'});
    const idx = count<65536 ? Uint16Array.from(out) : out;
    primitive.indices = append(idx,'TRIANGLES',idx.BYTES_PER_ELEMENT,idx.length,{
      componentType:count<65536?5123:5125,type:'SCALAR'});
  }
}
doc.bufferViews=views;
doc.accessors=accessors;
doc.extensionsRequired=['EXT_meshopt_compression'];
doc.extensionsUsed=['EXT_meshopt_compression'];
doc.buffers=[{byteLength:length},{byteLength:virtualLength,extensions:{EXT_meshopt_compression:{fallback:true}}}];
doc.asset.generator += ' / meshoptimizer';
const json = Buffer.from(JSON.stringify(doc));
const jsonPad = (4-json.length%4)%4, binPad = (4-length%4)%4;
const header = Buffer.alloc(20);
header.write('glTF');
header.writeUInt32LE(2,4);
header.writeUInt32LE(28+json.length+jsonPad+length+binPad,8);
header.writeUInt32LE(json.length+jsonPad,12);
header.write('JSON',16);
const binHdr = Buffer.alloc(8);
binHdr.writeUInt32LE(length+binPad,0);
binHdr.write('BIN\0',4);
fs.writeFileSync(output,Buffer.concat([header,json,Buffer.alloc(jsonPad,0x20),binHdr,...chunks,Buffer.alloc(binPad)]));
console.log({before,after,compression:Math.round(100*fs.statSync(output).size/raw.length)+'%',maxError,output});
